/** Phosphor duotone glyph. Sized/coloured by className + style, like the previous icons. */
function make(name) {
  const paths = P[name];
  // `weight` is accepted and ignored — these are duotone-only, but a caller may still
  // pass it. Swallowing it keeps it off the DOM (React warns on unknown attributes).
  // eslint-disable-next-line no-unused-vars -- `weight` is destructured purely to keep it off the DOM
  const C = ({ className = '', style, weight, ...rest }) => (
    <svg viewBox="0 0 256 256" fill="currentColor" className={className} style={style} aria-hidden="true" {...rest}>
      {paths.map(([d, opacity], i) => <path key={i} d={d} opacity={opacity} />)}
    </svg>
  );
  C.displayName = name;
  return C;
}

